-- 126_italian_titles_translated.sql
-- Fills the Italian titles still missing, from the list the Owner checked (Documentazione/Titoli_italiani_tradotti.md), and adds the mark that the
-- app shows beside a translated title (Owner's decision, 2026-11-06). Generated by Documentazione/titoli-italiani/costruisci_tradotti.mjs.
--   archive_title  the same Italian title already exists elsewhere in the archive, or is inside the English title
--   rule           Word of Life: only the month and the year
--   translation    translated from the English title, without opening the text: it may not be the real title. Only these get the mark.
-- It writes only empty it_title fields, on documents neither deleted nor reserved. No other title changes.
-- Changing an Italian title clears its mark, whichever screen does it, unless the same change also sets the mark.
-- Run it in the SQL Editor, BEFORE merging: the Library asks for the new column. It can be run twice. What it wrote is kept in a table, and undone like this:
--   update public.documents d set it_title = null, it_title_translated = false from public._filled_it_title_20261106 f where d.document_id = f.document_id and d.it_title = f.it_title and f.source in ('archive_title', 'rule', 'translation');

alter table public.documents add column if not exists it_title_translated boolean not null default false;

create or replace function public.documents_clear_it_title_mark()
returns trigger
language plpgsql
as $$
begin
  if new.it_title is distinct from old.it_title and new.it_title_translated = old.it_title_translated then
    new.it_title_translated := false;
  end if;
  return new;
end;
$$;

drop trigger if exists documents_clear_it_title_mark on public.documents;
create trigger documents_clear_it_title_mark
  before update on public.documents
  for each row execute function public.documents_clear_it_title_mark();

