), done as (
  update public.documents d
  set it_title = p.it_title,
      it_title_translated = (p.source = 'translation')
  from proposed p
  where p.document_id = d.document_id
    and nullif(btrim(d.it_title), '') is null
    and d.deleted_at is null
    and d.access_level <> 'reserved'
  returning d.document_id, d.it_title, p.source
)
insert into public._filled_it_title_20261106 (document_id, it_title, source)
select document_id, it_title, source from done
on conflict (document_id) do nothing;

-- Verification (the SQL Editor shows only the last result). Eight rows. marked must equal filled: translation.
-- works_without_italian should fall to about 62: the Works left out of the list.
with o as (
  select coalesce('w' || d.work_id::text, 'd' || d.document_id::text) as opera,
         count(distinct lower(btrim(d.it_title))) as titoli
  from public.documents d
  where d.deleted_at is null
  group by 1
)
select ord, what, n from (
  select 1 as ord, 'column and trigger' as what,
         (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'documents' and column_name = 'it_title_translated')
         + (select count(*) from pg_trigger where tgname = 'documents_clear_it_title_mark') as n
  union all select 2, 'filled: archive_title', count(*) from public._filled_it_title_20261106 where source = 'archive_title'
  union all select 3, 'filled: rule', count(*) from public._filled_it_title_20261106 where source = 'rule'
  union all select 4, 'filled: translation', count(*) from public._filled_it_title_20261106 where source = 'translation'
  union all select 5, 'marked', count(*) from public.documents where it_title_translated
  union all select 6, 'works', count(*) from o
  union all select 7, 'works_with_italian', count(*) from o where titoli > 0
  union all select 8, 'works_without_italian', count(*) from o where titoli = 0
) r
order by ord;
